local Controller=include("rhenium_hot_object_round/controller.lua");local Names={HookPrefix="rhenium_hot_object_round",TimerName="rhenium_hot_object_round.tick"};local S={};local core,installed=nil,false;local bindings,objects={},{};local seq=0;local function find(rows,o)for _,r in ipairs(rows)do if r.object==o then return r end end end;local function validid(v)return type(v)=="string"and#v>0 and#v<=128 and v:match("^[%w][%w_.:%-]*$")end;local function validrev(v)return type(v)=="number"and v>=1 and v%1==0 and v<math.huge end;local function restore(e,b)if b then e.StartTouch=b.old_start;e.Touch=b.old_touch end end
function S.Install(o)if installed then return S end;o=o or{};core=assert(Controller.new({object_id=o.object_id or"hot:1",object_revision=o.object_revision or 1,state=o.state}));hook.Add("PlayerDeath",Names.HookPrefix..".PlayerDeath",function(p)local b=find(bindings,p);if b then core:death("death:"..b.id..":"..b.revision,b.id,b.revision,CurTime())end end);hook.Add("PlayerSpawn",Names.HookPrefix..".PlayerSpawn",function(p)local b=find(bindings,p);if b and b.spawned then local old=b.revision;b.revision=old+1;core:respawn("respawn:"..b.id..":"..b.revision,b.id,old,b.revision,CurTime())elseif b then b.spawned=true end end);hook.Add("PlayerDisconnected",Names.HookPrefix..".PlayerDisconnected",function(p)local b=find(bindings,p);if b then core:disconnect("disconnect:"..b.id..":"..b.revision,b.id,b.revision,CurTime())end;for i=#bindings,1,-1 do if bindings[i].object==p then table.remove(bindings,i)end end end);hook.Add("EntityRemoved",Names.HookPrefix..".EntityRemoved",function(e)for i=#objects,1,-1 do if objects[i].object==e then restore(e,objects[i]);table.remove(objects,i)end end end);timer.Create(Names.TimerName,.05,0,function()if core then core:tick(CurTime())end end);installed=true;return S end
function S.BindPlayer(p,id,r)r=r or 1;if not installed or not IsValid(p)or not p:IsPlayer()or not validid(id)or not validrev(r)then return false end;bindings[#bindings+1]={object=p,id=id,revision=r,spawned=true};return true end
function S.BindObject(e,id,r)if not installed or not IsValid(e)or not validid(id)or not validrev(r)or find(objects,e)then return false end;local row={object=e,id=id,revision=r,old_start=e.StartTouch,old_touch=e.Touch};objects[#objects+1]=row;e.StartTouch=function(self,x)if row.old_start then row.old_start(self,x)end;S.Dispatch({kind="touch",object=self,player=x})end;e.Touch=function(self,x)if row.old_touch then row.old_touch(self,x)end;S.Dispatch({kind="touch",object=self,player=x})end;return true end
function S.StartRound(rid,round_id,v,list,h,d)local ids={};for _,p in ipairs(list)do local b=find(bindings,p);if not b then return false,"unbound",{}end;ids[#ids+1]=b.id end;local holder=find(bindings,h);if not holder then return false,"unbound",{}end;return core:start(rid,round_id,v,ids,holder.id,d)end
function S.Dispatch(e)if type(e)~="table"then return false,"invalid_event",{}end;if e.kind=="touch"then local o,p=find(objects,e.object),find(bindings,e.player);if not o or not p then return false,"unbound",{}end;seq=seq+1;return core:touch(e.event_id or("touch:"..seq),o.id,o.revision,p.id,p.revision,e.sequence or seq,e.now or CurTime())end;return false,"invalid_kind",{}end
function S.Snapshot()return core and core:snapshot(CurTime())end;function S.Save()return core and core:save(CurTime())end;function S.Shutdown()if installed then for _,x in ipairs({{"PlayerDeath",".PlayerDeath"},{"PlayerSpawn",".PlayerSpawn"},{"PlayerDisconnected",".PlayerDisconnected"},{"EntityRemoved",".EntityRemoved"}})do hook.Remove(x[1],Names.HookPrefix..x[2])end;timer.Remove(Names.TimerName);installed=false end;for _,b in ipairs(objects)do restore(b.object,b)end;if core then core:shutdown()end;bindings={};objects={};seq=0;return true,"shutdown"end;return S
